1	import { Injectable, effect, signal } from '@angular/core';
2	import { CountryStore } from './country.store';
3	import type { Step1FormValue } from '../models/form-field.model';
4	import type {
5	  PaymentStatus,
6	  SelectedPlan,
7	  SimulatedPaymentResult,
8	  Step1Status,
9	  WizardState,
10	} from '../models/wizard.model';
11	
12	const STORAGE_KEY = 'quote.wizard';
13	
14	function createInitialState(): WizardState {
15	  return {
16	    step1: { value: {}, status: 'loading' },
17	    selectedPlan: null,
18	    terms: { accepted: false, acceptedVersion: null },
19	    payment: { status: 'idle', result: null },
20	  };
21	}
22	
23	@Injectable({ providedIn: 'root' })
24	export class WizardStore {
25	  private readonly stateSignal = signal<WizardState>(readStoredState() ?? createInitialState());
26	
27	  readonly state = this.stateSignal.asReadonly();
28	
29	  constructor(private readonly countryStore: CountryStore) {
30	    effect(() => {
31	      persistState(this.stateSignal());
32	    });
33	
34	    let previousCountry = this.countryStore.country();
35	    effect(() => {
36	      const country = this.countryStore.country();
37	      if (previousCountry !== null && country !== previousCountry) {
38	        this.stateSignal.set(createInitialState());
39	      }
40	      previousCountry = country;
41	    });
42	  }
43	
44	  setStep1Value(value: Step1FormValue): void {
45	    this.stateSignal.update((state) => ({ ...state, step1: { ...state.step1, value } }));
46	  }
47	
48	  setStep1Status(status: Step1Status): void {
49	    this.stateSignal.update((state) => ({ ...state, step1: { ...state.step1, status } }));
50	  }
51	
52	  selectPlan(plan: SelectedPlan): void {
53	    this.stateSignal.update((state) => ({ ...state, selectedPlan: plan }));
54	  }
55	
56	  clearSelectedPlan(): void {
57	    this.stateSignal.update((state) => ({ ...state, selectedPlan: null }));
58	  }
59	
60	  acceptTerms(version: string): void {
61	    this.stateSignal.update((state) => ({
62	      ...state,
63	      terms: { accepted: true, acceptedVersion: version },
64	    }));
65	  }
66	
67	  setPaymentStatus(status: PaymentStatus): void {
68	    this.stateSignal.update((state) => ({ ...state, payment: { ...state.payment, status } }));
69	  }
70	
71	  setPaymentResult(result: SimulatedPaymentResult | null): void {
72	    this.stateSignal.update((state) => ({ ...state, payment: { ...state.payment, result } }));
73	  }
74	
75	  reset(): void {
76	    this.stateSignal.set(createInitialState());
77	  }
78	}
79	
80	function readStoredState(): WizardState | null {
81	  try {
82	    const raw = sessionStorage.getItem(STORAGE_KEY);
83	    return raw ? (JSON.parse(raw) as WizardState) : null;
84	  } catch {
85	    return null;
86	  }
87	}
88	
89	function persistState(state: WizardState): void {
90	  try {
91	    sessionStorage.setItem(STORAGE_KEY, JSON.stringify(state));
92	  } catch {
93	    // sessionStorage unavailable: wizard state won't survive a refresh in this session.
94	  }
95	}
