1	import { HttpClient, HttpParams } from '@angular/common/http';
2	import { Injectable, Signal, effect, inject, signal } from '@angular/core';
3	import { Observable, map } from 'rxjs';
4	import { environment } from '../../../environments/environment';
5	import { CountryStore } from '../state/country.store';
6	import type { CountryCode } from '../models/country.model';
7	import type { FormFieldEntry } from '../models/form-field.model';
8	import type { PlanEntry } from '../models/plan.model';
9	import type { StrapiCollectionResponse } from '../models/strapi.model';
10	import type { TermsAndConditionEntry } from '../models/terms.model';
11	
12	export interface CountryContentState<T> {
13	  readonly data: T | null;
14	  readonly loading: boolean;
15	  readonly error: string | null;
16	}
17	
18	function noCountrySelectedState<T>(): CountryContentState<T> {
19	  return { data: null, loading: false, error: 'No country selected.' };
20	}
21	
22	@Injectable({ providedIn: 'root' })
23	export class CountryContentService {
24	  private readonly http = inject(HttpClient);
25	  private readonly countryStore = inject(CountryStore);
26	
27	  private readonly formFieldsRefresh = signal(0);
28	  private readonly plansRefresh = signal(0);
29	  private readonly termsRefresh = signal(0);
30	
31	  private readonly formFieldsState = this.createCountryScopedState<FormFieldEntry[]>(
32	    (country) =>
33	      this.http
34	        .get<StrapiCollectionResponse<FormFieldEntry>>(`${environment.strapiApiBaseUrl}/form-fields`, {
35	          params: new HttpParams()
36	            .set('filters[country][$eq]', country)
37	            .set('sort', 'order:asc,id:asc')
38	            .set('pagination[pageSize]', '100'),
39	        })
40	        .pipe(map((response) => response.data)),
41	    this.formFieldsRefresh,
42	  );
43	
44	  private readonly plansState = this.createCountryScopedState<PlanEntry[]>(
45	    (country) =>
46	      this.http
47	        .get<StrapiCollectionResponse<PlanEntry>>(`${environment.strapiApiBaseUrl}/plans`, {
48	          params: new HttpParams()
49	            .set('filters[country][$eq]', country)
50	            .set('filters[active][$eq]', 'true')
51	            .set('sort', 'order:asc,id:asc')
52	            .set('populate', '*')
53	            .set('pagination[pageSize]', '100'),
54	        })
55	        .pipe(map((response) => response.data)),
56	    this.plansRefresh,
57	  );
58	
59	  private readonly termsState = this.createCountryScopedState<TermsAndConditionEntry | null>(
60	    (country) =>
61	      this.http
62	        .get<StrapiCollectionResponse<TermsAndConditionEntry>>(
63	          `${environment.strapiApiBaseUrl}/terms-and-conditions`,
64	          {
65	            params: new HttpParams()
66	              .set('filters[country][$eq]', country)
67	              .set('sort', 'id:asc')
68	              .set('pagination[pageSize]', '1'),
69	          },
70	        )
71	        .pipe(map((response) => response.data[0] ?? null)),
72	    this.termsRefresh,
73	  );
74	
75	  getFormFields(): Signal<CountryContentState<FormFieldEntry[]>> {
76	    return this.formFieldsState;
77	  }
78	
79	  getPlans(): Signal<CountryContentState<PlanEntry[]>> {
80	    return this.plansState;
81	  }
82	
83	  getTerms(): Signal<CountryContentState<TermsAndConditionEntry | null>> {
84	    return this.termsState;
85	  }
86	
87	  /** Re-issues the form-fields request for the current country (e.g. after a load error). */
88	  refetchFormFields(): void {
89	    this.formFieldsRefresh.update((n) => n + 1);
90	  }
91	
92	  /** Re-issues the plans request for the current country (e.g. after a load error). */
93	  refetchPlans(): void {
94	    this.plansRefresh.update((n) => n + 1);
95	  }
96	
97	  /** Re-issues the terms request for the current country (e.g. after a load error). */
98	  refetchTerms(): void {
99	    this.termsRefresh.update((n) => n + 1);
100	  }
101	
102	  private createCountryScopedState<T>(
103	    request: (country: CountryCode) => Observable<T>,
104	    refresh: Signal<number>,
105	  ): Signal<CountryContentState<T>> {
106	    const state = signal<CountryContentState<T>>(noCountrySelectedState<T>());
107	    let fetchedForCountry: CountryCode | null = null;
108	    let fetchedForRefreshToken: number | null = null;
109	
110	    effect(() => {
111	      const country = this.countryStore.country();
112	      const refreshToken = refresh();
113	
114	      if (!country) {
115	        fetchedForCountry = null;
116	        fetchedForRefreshToken = null;
117	        state.set(noCountrySelectedState<T>());
118	        return;
119	      }
120	
121	      if (country === fetchedForCountry && refreshToken === fetchedForRefreshToken) {
122	        return;
123	      }
124	
125	      fetchedForCountry = country;
126	      fetchedForRefreshToken = refreshToken;
127	      state.set({ data: null, loading: true, error: null });
128	
129	      request(country).subscribe({
130	        next: (data) => state.set({ data, loading: false, error: null }),
131	        error: (error: unknown) =>
132	          state.set({ data: null, loading: false, error: toErrorMessage(error) }),
133	      });
134	    });
135	
136	    return state.asReadonly();
137	  }
138	}
139	
140	function toErrorMessage(error: unknown): string {
141	  if (error instanceof Error) {
142	    return error.message;
143	  }
144	  return 'Failed to load content from the CMS.';
145	}
