29	  const age = calculateAge(dateOfBirth, referenceDate);
30	  if (age === null) {
31	    return 1;
32	  }
33	  if (age < 25) {
34	    return 1.15;
35	  }
36	  if (age > 60) {
37	    return 1.05;
38	  }
39	  return 1;
40	}
41	
42	export function vehicleAgeFactor(vehicleYear: number | null, currentYear: number = new Date().getFullYear()): number {
43	  if (vehicleYear === null) {
44	    return 1;
45	  }
46	  return currentYear - vehicleYear > 10 ? 1.1 : 1;
47	}
48	
49	export function usageFactor(vehicleUsage: VehicleUsage | null): number {
50	  return vehicleUsage === 'commercial' ? 1.2 : 1;
51	}
52	
53	function calculateAge(dateOfBirth: string | null, referenceDate: Date): number | null {
54	  if (!dateOfBirth) {
55	    return null;
56	  }
57	
58	  const dob = new Date(dateOfBirth);
59	  if (Number.isNaN(dob.getTime())) {
60	    return null;
61	  }
62	
63	  let age = referenceDate.getFullYear() - dob.getFullYear();
64	  const birthdayPassedThisYear =
65	    referenceDate.getMonth() > dob.getMonth() ||
66	    (referenceDate.getMonth() === dob.getMonth() && referenceDate.getDate() >= dob.getDate());
67	  if (!birthdayPassedThisYear) {
68	    age -= 1;
69	  }
70	
71	  return age;
72	}
