74	/**
75	 * Reads the reserved keys (ADR-0002) the pricing rule depends on out of the dynamic
76	 * step-1 map. A missing or mistyped key falls back to "no adjustment for that factor"
77	 * rather than guessing a business meaning or throwing.
78	 */
79	export function extractPricingInputFromStep1(step1: Step1FormValue): SimulatedPricingRuleInput {
80	  const dateOfBirth = step1['dateOfBirth'];
81	  const vehicleYear = step1['vehicleYear'];
82	  const vehicleUsage = step1['vehicleUsage'];
83	
84	  return {
85	    dateOfBirth: typeof dateOfBirth === 'string' && dateOfBirth !== '' ? dateOfBirth : null,
86	    vehicleYear: typeof vehicleYear === 'number' ? vehicleYear : null,
87	    vehicleUsage: vehicleUsage === 'personal' || vehicleUsage === 'commercial' ? vehicleUsage : null,
88	  };
89	}
