104	@Component({
105	  selector: 'app-quote-form-page',
106	  imports: [ReactiveFormsModule],
107	  templateUrl: './quote-form-page.component.html',
108	  styleUrl: './quote-form-page.component.scss',
109	})
110	export class QuoteFormPageComponent {
111	  private readonly countryContentService = inject(CountryContentService);
112	  private readonly wizardStore = inject(WizardStore);
113	  private readonly router = inject(Router);
114	  private readonly destroyRef = inject(DestroyRef);
115	
116	  private readonly fieldsState = this.countryContentService.getFormFields();
117	
118	  readonly loading = computed(() => this.fieldsState().loading);
119	  readonly error = computed(() => this.fieldsState().error);
120	  readonly fields = computed(() => this.fieldsState().data ?? []);
121	
122	  readonly isEmpty = computed(() => {
123	    const state = this.fieldsState();
124	    return !state.loading && !state.error && state.data !== null && state.data.length === 0;
125	  });
126	
127	  readonly form = signal<Step1FormGroup | null>(null);
128	  readonly submitted = signal(false);
129	
130	  readonly hasAnyMisconfiguredSelect = computed(() =>
131	    this.fields().some((field) => this.hasMisconfiguredSelect(field)),
132	  );
133	
134	  private formSubscriptionCleanup: (() => void) | null = null;
135	
136	  constructor() {
137	    effect(() => {
138	      const state = this.fieldsState();
139	
140	      if (state.loading) {
141	        this.wizardStore.setStep1Status('loading');
142	        return;
143	      }
144	
145	      if (state.error) {
146	        this.wizardStore.setStep1Status('error');
147	        this.form.set(null);
148	        return;
149	      }
150	
151	      if (!state.data) {
152	        return;
153	      }
154	
155	      if (state.data.length === 0) {
156	        this.wizardStore.setStep1Status('empty');
157	        this.form.set(null);
158	        return;
159	      }
160	
161	      this.wizardStore.setStep1Status('ready');
162	      this.initializeForm(state.data);
163	    });
164	
165	    this.destroyRef.onDestroy(() => this.formSubscriptionCleanup?.());
166	  }
167	
168	  private initializeForm(fields: FormFieldEntry[]): void {
169	    const existingValue = untracked(() => this.wizardStore.state().step1.value);
170	    const group = buildStep1FormGroup(fields, existingValue);
171	
172	    if (Object.keys(existingValue).length > 0) {
173	      group.markAllAsTouched();
174	    }
175	
176	    this.formSubscriptionCleanup?.();
177	    const subscription = group.valueChanges.subscribe((value) => {
178	      this.wizardStore.setStep1Value(value as Step1FormValue);
179	    });
180	    this.formSubscriptionCleanup = () => subscription.unsubscribe();
181	
182	    this.wizardStore.setStep1Value(group.getRawValue());
183	    this.form.set(group);
184	  }
185	
186	  getControl(field: FormFieldEntry): FormControl<FormFieldValue> | undefined {
187	    return this.form()?.controls[field.key];
188	  }
189	
190	  // `FormGroup.valid` mutates in place as controls change; it must be read directly
191	  // in a plain method (re-evaluated every change detection pass), not memoized via
192	  // `computed()`, which would only track the `form` signal reference itself.
193	  canContinue(): boolean {
194	    const form = this.form();
195	    return !!form && form.valid && !this.hasAnyMisconfiguredSelect();
196	  }
197	
198	  hasMisconfiguredSelect(field: FormFieldEntry): boolean {
199	    return field.type === 'select' && (!field.options || field.options.length === 0);
200	  }
201	
202	  showError(field: FormFieldEntry): boolean {
203	    const control = this.getControl(field);
204	    if (!control) {
205	      return false;
206	    }
207	    return control.invalid && (control.touched || control.dirty || this.submitted());
208	  }
209	
210	  errorId(field: FormFieldEntry): string {
211	    return `field-${field.key}-error`;
212	  }
213	
214	  helpId(field: FormFieldEntry): string {
215	    return `field-${field.key}-help`;
216	  }
217	
218	  describedBy(field: FormFieldEntry): string | null {
219	    const ids: string[] = [];
220	    if (field.helpText) {
221	      ids.push(this.helpId(field));
222	    }
223	    if (this.showError(field)) {
224	      ids.push(this.errorId(field));
225	    }
226	    return ids.length > 0 ? ids.join(' ') : null;
227	  }
228	
229	  retry(): void {
230	    this.countryContentService.refetchFormFields();
231	  }
232	
233	  onSubmit(): void {
234	    this.submitted.set(true);
235	    const form = this.form();
236	    if (!form || form.invalid || this.hasAnyMisconfiguredSelect()) {
237	      form?.markAllAsTouched();
238	      return;
239	    }
240	
241	    this.wizardStore.setStep1Value(form.getRawValue());
242	    this.router.navigate(['/quote/plans']);
243	  }
244	}
245

1	<section class="quote-form-page">
2	  <h1>Step 1 — Policyholder and vehicle data</h1>
3	
4	  @if (loading()) {
5	    <div class="quote-form-page__status" role="status" aria-live="polite">
6	      <p>Loading form fields…</p>
7	    </div>
8	  } @else if (error(); as errorMessage) {
9	    <div class="quote-form-page__status quote-form-page__status--error" role="alert">
10	      <p>We couldn't load the form: {{ errorMessage }}</p>
11	      <button type="button" (click)="retry()">Retry</button>
12	    </div>
13	  } @else if (isEmpty()) {
14	    <div class="quote-form-page__status" role="status">
15	      <p>No fields are configured for this country yet. Please contact the business team.</p>
16	    </div>
17	  } @else if (form(); as formGroup) {
18	    <form class="quote-form-page__form" [formGroup]="formGroup" (ngSubmit)="onSubmit()" novalidate>
19	      @for (field of fields(); track field.id) {
20	        <div class="quote-form-page__field">
21	          @if (hasMisconfiguredSelect(field)) {
22	            <p class="quote-form-page__field-config-error" role="alert">
23	              "{{ field.label }}" is misconfigured — contact the business team.
24	            </p>
25	          } @else {
26	            <label [for]="'field-' + field.key">
27	              {{ field.label }}
28	              @if (field.required) {
29	                <span aria-hidden="true">*</span>
30	              }
31	            </label>
32	
33	            @switch (field.type) {
34	              @case ('text') {
35	                <input
36	                  [id]="'field-' + field.key"
37	                  type="text"
38	                  [formControlName]="field.key"
39	                  [attr.aria-describedby]="describedBy(field)"
40	                  [attr.aria-invalid]="showError(field)"
41	                />
42	              }
43	              @case ('number') {
44	                <input
45	                  [id]="'field-' + field.key"
46	                  type="number"
47	                  [formControlName]="field.key"
48	                  [attr.aria-describedby]="describedBy(field)"
49	                  [attr.aria-invalid]="showError(field)"
50	                />
51	              }
52	              @case ('date') {
53	                <input
54	                  [id]="'field-' + field.key"
55	                  type="date"
56	                  [formControlName]="field.key"
57	                  [attr.aria-describedby]="describedBy(field)"
58	                  [attr.aria-invalid]="showError(field)"
59	                />
60	              }
61	              @case ('checkbox') {
62	                <input
63	                  [id]="'field-' + field.key"
64	                  type="checkbox"
65	                  [formControlName]="field.key"
66	                  [attr.aria-describedby]="describedBy(field)"
67	                  [attr.aria-invalid]="showError(field)"
68	                />
69	              }
70	              @case ('select') {
71	                <select
72	                  [id]="'field-' + field.key"
73	                  [formControlName]="field.key"
74	                  [attr.aria-describedby]="describedBy(field)"
75	                  [attr.aria-invalid]="showError(field)"
76	                >
77	                  <option value="" disabled>Select…</option>
78	                  @for (option of field.options; track option.value) {
79	                    <option [value]="option.value">{{ option.label }}</option>
80	                  }
81	                </select>
82	              }
83	            }
84	
85	            @if (field.helpText) {
86	              <p class="quote-form-page__help" [id]="helpId(field)">{{ field.helpText }}</p>
87	            }
88	            @if (showError(field)) {
89	              <p class="quote-form-page__error" [id]="errorId(field)" role="alert">{{ field.errorMessage }}</p>
90	            }
91	          }
92	        </div>
93	      }
94	
95	      <button type="submit" [disabled]="!canContinue()">Continue</button>
96	    </form>
97	  }
98	</section>
