1	import { Component, computed, effect, inject, untracked } from '@angular/core';
2	import { Router } from '@angular/router';
3	import { CountryContentService } from '../../../core/services/country-content.service';
4	import { CountryStore } from '../../../core/state/country.store';
5	import { WizardStore } from '../../../core/state/wizard.store';
6	import {
7	  applySimulatedPricingRule,
8	  extractPricingInputFromStep1,
9	  type SimulatedPricingRuleInput,
10	} from '../../../core/pricing/simulated-pricing-rule';
11	import type { CountryCode } from '../../../core/models/country.model';
12	import type { Currency, PlanDetailItem, PlanEntry } from '../../../core/models/plan.model';
13	import type { SelectedPlan } from '../../../core/models/wizard.model';
14	
15	export interface PlanViewModel {
16	  id: number;
17	  name: string;
18	  shortDescription: string;
19	  adjustedPrice: number;
20	  formattedPrice: string;
21	  currency: Currency;
22	  coverages: PlanDetailItem[];
23	  benefits: PlanDetailItem[];
24	  recommended: boolean;
25	}
26	
27	const LOCALE_BY_COUNTRY: Record<CountryCode, string> = {
28	  CO: 'es-CO',
29	  CL: 'es-CL',
30	};
31	
32	function formatPrice(amount: number, currency: Currency, locale: string): string {
33	  return new Intl.NumberFormat(locale, {
34	    style: 'currency',
35	    currency,
36	    maximumFractionDigits: 0,
37	  }).format(amount);
38	}
39	
40	function toViewModel(entry: PlanEntry, pricingInput: SimulatedPricingRuleInput, locale: string): PlanViewModel {
41	  const adjustedPrice = applySimulatedPricingRule(entry.basePrice, pricingInput);
42	
43	  return {
44	    id: entry.id,
45	    name: entry.name,
46	    shortDescription: entry.shortDescription,
47	    adjustedPrice,
48	    formattedPrice: formatPrice(adjustedPrice, entry.currency, locale),
49	    currency: entry.currency,
50	    coverages: entry.coverages,
51	    benefits: entry.benefits,
52	    recommended: entry.recommended,
53	  };
54	}
