56	@Component({
57	  selector: 'app-quote-plans-page',
58	  imports: [],
59	  templateUrl: './quote-plans-page.component.html',
60	  styleUrl: './quote-plans-page.component.scss',
61	})
62	export class QuotePlansPageComponent {
63	  private readonly countryContentService = inject(CountryContentService);
64	  private readonly countryStore = inject(CountryStore);
65	  private readonly wizardStore = inject(WizardStore);
66	  private readonly router = inject(Router);
67	
68	  private readonly plansState = this.countryContentService.getPlans();
69	
70	  readonly loading = computed(() => this.plansState().loading);
71	  readonly error = computed(() => this.plansState().error);
72	
73	  readonly isEmpty = computed(() => {
74	    const state = this.plansState();
75	    return !state.loading && !state.error && state.data !== null && state.data.length === 0;
76	  });
77	
78	  readonly selectedPlanId = computed(() => this.wizardStore.state().selectedPlan?.id ?? null);
79	
80	  readonly plans = computed<PlanViewModel[]>(() => {
81	    const entries = this.plansState().data ?? [];
82	    const country = this.countryStore.country();
83	    const locale = country ? LOCALE_BY_COUNTRY[country] : LOCALE_BY_COUNTRY.CO;
84	    const pricingInput = extractPricingInputFromStep1(this.wizardStore.state().step1.value);
85	
86	    return entries.map((entry) => toViewModel(entry, pricingInput, locale));
87	  });
88	
89	  constructor() {
90	    // Re-validates a persisted selection against the freshly fetched active+published
91	    // list whenever that list (re)loads — e.g. returning from the summary step or
92	    // re-entering after a stale sessionStorage restore. `untracked` keeps this from
93	    // re-running on every wizard-state change (e.g. a selection it just made).
94	    effect(() => {
95	      const state = this.plansState();
96	      if (state.loading || state.error || state.data === null) {
97	        return;
98	      }
99	
100	      const data = state.data;
101	      const selected = untracked(() => this.wizardStore.state().selectedPlan);
102	      if (selected && !data.some((plan) => plan.id === selected.id)) {
103	        this.wizardStore.clearSelectedPlan();
104	      }
105	    });
106	  }
107	
108	  selectPlan(plan: PlanViewModel): void {
109	    const country = this.countryStore.country();
110	    if (!country) {
111	      return;
112	    }
113	
114	    const selected: SelectedPlan = {
115	      id: plan.id,
116	      name: plan.name,
117	      country,
118	      finalPrice: plan.adjustedPrice,
119	      currency: plan.currency,
120	      coverageSummary: plan.coverages.map((coverage) => coverage.name),
121	    };
122	    this.wizardStore.selectPlan(selected);
123	  }
124	
125	  canContinue(): boolean {
126	    return this.selectedPlanId() !== null;
127	  }
128	
129	  continue(): void {
130	    this.router.navigate(['/quote/summary']);
131	  }
132	
133	  retry(): void {
134	    this.countryContentService.refetchPlans();
135	  }
136	}
