input.content:
.quote-summary-page {
  max-width: 56rem;
  margin: 0 auto;
  padding: 1rem;

  &__confirmation {
    padding: 1.5rem;
    border-radius: 0.5rem;
    background: #e3f6e9;
    border: 1px solid #0d5c2b;
    color: #0d5c2b;

    &:focus-visible,
    &:focus {
      outline: 2px solid #0d5c2b;
      outline-offset: 2px;
    }
  }

  &__grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: 1rem;
    margin-bottom: 1rem;
  }

  &__card {
    border: 1px solid #ccc;
    border-radius: 0.5rem;
    padding: 1rem;

    h2 {
      margin-top: 0;
      font-size: 1.05rem;
    }

    dl {
      margin: 0;
    }

    dl > div {
      display: flex;
      justify-content: space-between;
      gap: 0.5rem;
      padding: 0.25rem 0;
      border-bottom: 1px solid #eee;

      &:last-child {
        border-bottom: none;
      }
    }

    dt {
      font-weight: 600;
      color: #444;
    }

    dd {
      margin: 0;
      text-align: right;
    }
  }

  &__plan-name {
    font-weight: 600;
    margin: 0 0 0.25rem;
  }

  &__plan-price {
    font-size: 1.25rem;
    font-weight: 700;
    margin: 0 0 0.5rem;
  }

  &__nav {
    display: flex;
    gap: 1rem;
    margin-bottom: 1.5rem;

    a {
      color: #1a73e8;

      &:focus-visible {
        outline: 2px solid #1a73e8;
        outline-offset: 2px;
      }
    }
  }

  &__terms {
    margin-bottom: 1.5rem;
  }

  &__terms-body {
    white-space: pre-wrap;
    max-height: 16rem;
    overflow-y: auto;
    padding: 0.75rem;
    border: 1px solid #ccc;
    border-radius: 0.5rem;
    background: #fafafa;
    margin-bottom: 0.5rem;
  }

  &__terms-help {
    font-size: 0.85rem;
    color: #555;
    margin: 0 0 0.5rem;
  }

  &__terms-checkbox {
    display: flex;
    align-items: flex-start;
    gap: 0.5rem;

    input {
      width: 1.1rem;
      height: 1.1rem;
      margin-top: 0.15rem;

      &:focus-visible {
        outline: 2px solid #1a73e8;
        outline-offset: 2px;
      }
    }

    label {
      font-weight: 600;
    }
  }

  &__status {
    padding: 1rem;
    border-radius: 0.5rem;
    background: #f5f5f5;

    &--error {
      background: #fdecea;
      color: #611a15;
    }
  }

  &__pay {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    align-items: flex-start;

    button[type='button'] {
      padding: 0.6rem 1.25rem;
      border: none;
      border-radius: 0.25rem;
      background: #1a73e8;
      color: #fff;
      font-weight: 600;
      cursor: pointer;

      &:disabled {
        background: #a9c4ec;
        cursor: not-allowed;
      }

      &:focus-visible {
        outline: 2px solid #0d47a1;
        outline-offset: 2px;
      }
    }
  }

  &__error {
    padding: 1rem;
    border-radius: 0.5rem;
    background: #fdecea;
    color: #611a15;
    border: 1px solid #b42318;

    &:focus-visible,
    &:focus {
      outline: 2px solid #b42318;
      outline-offset: 2px;
    }
  }

  .quote-summary-page__status button[type='button'],
  .quote-summary-page__terms .quote-summary-page__status button[type='button'] {
    margin-top: 0.5rem;
    padding: 0.5rem 1rem;
    border: 1px solid #1a73e8;
    border-radius: 0.25rem;
    background: #fff;
    color: #1a73e8;
    cursor: pointer;

    &:focus-visible {
      outline: 2px solid #1a73e8;
      outline-offset: 2px;
    }
  }
}

@media (max-width: 40rem) {
  .quote-summary-page {
    &__card dl > div {
      flex-direction: column;
      align-items: flex-start;
    }

    &__card dd {
      text-align: left;
    }

    &__nav {
      flex-direction: column;
    }
  }
}

