$ports = 4200,1337
foreach ($p in $ports) {
  $conns = Get-NetTCPConnection -LocalPort $p -State Listen -ErrorAction SilentlyContinue
  foreach ($c in $conns) {
    Write-Output "Killing PID $($c.OwningProcess) on port $p"
    Stop-Process -Id $c.OwningProcess -Force -ErrorAction SilentlyContinue
  }
}
Start-Sleep -Seconds 2
Get-NetTCPConnection -LocalPort 4200,1337 -State Listen -ErrorAction SilentlyContinue

